import { useState } from 'react';

export function Segmented() {
  const opts = {{options}};
  const [val, setVal] = useState(opts[0].value);
  return (
    <div className="inline-flex rounded-lg bg-gray-100 p-1">
      {opts.map((o) => (
        <button key={o.value} onClick={() => setVal(o.value)}
          className={`rounded-md px-4 py-1.5 text-sm font-medium ${val === o.value ? 'bg-white shadow' : 'text-gray-600'}`}>
          {o.label}
        </button>
      ))}
    </div>
  );
}
